/**
 * Маленькие настоящие картинки для проверки перекодировки в стикер. Двоичных файлов в
 * репозитории нет, поэтому они лежат здесь строками base64.
 *
 * Сделаны ImageMagick 6.9 (libjpeg, libpng) — то есть не тем кодом, который их читает:
 *   photo-base.jpg — 45×31, плавные цвета, обычный JPEG, цвет прорежен 4:2:0 (-quality 82);
 *   photo-prog.jpg — те же точки и то же качество, но прогрессивный JPEG;
 *   figure.jpg     — 64×64, красный круг с тёмным контуром и синим пятном на белом листе;
 *   figure.png     — 40×30, PNG с прозрачностью (RGBA): зелёный круг, жёлтый квадрат;
 *   palette.png    — 24×16, PNG с палитрой, 2 бита на точку;
 *   deep.png       — 23×17, серый PNG, 16 бит на точку: градиент сверху вниз.
 * `SAMPLES` — точки [x, y, r, g, b, a], как их прочёл сам ImageMagick: с ними сверяется разбор.
 */
const bytes = (text) => new Uint8Array(Buffer.from(text, "base64"));

